-- DB08 F1 structural/ACL acceptance; synthetic owner writes are not workflow acceptance.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(73);
SELECT is((SELECT count(*) FROM pg_class WHERE relnamespace='app_private'::regnamespace AND relname IN ('finance_currency_units','finance_fee_categories','finance_fee_rules','finance_fee_rule_revisions','finance_fee_obligations') AND relkind='r' AND relrowsecurity AND relforcerowsecurity AND pg_get_userbyid(relowner)='schoolos_schema_owner'),5::bigint,'five Finance-owned forced-RLS tables');
