SELECT ok(NOT EXISTS(SELECT FROM pg_class WHERE relnamespace='app_private'::regnamespace AND relname IN ('finance_currency_units','finance_fee_categories','finance_fee_rules','finance_fee_rule_revisions','finance_fee_obligations') AND has_table_privilege('schoolos_evidence_writer',oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'schoolos_evidence_writer has no raw Finance privileges');
SELECT ok(NOT EXISTS(SELECT FROM pg_class WHERE relnamespace='app_private'::regnamespace AND relname IN ('finance_currency_units','finance_fee_categories','finance_fee_rules','finance_fee_rule_revisions','finance_fee_obligations') AND has_table_privilege('schoolos_file_login',oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'schoolos_file_login has no raw Finance privileges');
