SELECT ok(NOT has_function_privilege('authenticated','app_private.db08_validate_financial_context()','EXECUTE'),'no client helper execution');
SELECT is((SELECT count(*) FROM pg_proc WHERE pronamespace='app_private'::regnamespace AND proname IN('db08_validate_financial_context','db08_retain_financial_source') AND NOT prosecdef AND proconfig=ARRAY['search_path=pg_catalog, pg_temp']::text[]),2::bigint,'guards are invokers with fixed search path');
SELECT is((SELECT count(*) FROM pg_constraint WHERE conrelid IN(SELECT oid FROM pg_class WHERE relnamespace='app_private'::regnamespace AND relname IN ('finance_currency_units','finance_fee_categories','finance_fee_rules','finance_fee_rule_revisions','finance_fee_obligations')) AND contype='f' AND (confdeltype<>'r' OR confupdtype<>'r')),0::bigint,'financial ancestry never cascades');
